 const louver=unit('louver','PVC wooden louver panel','louver',21*I,15*I,40.74*I,30*I,0,walnut);box(louver.group,louver.w,louver.h,.012,0,0,-.525,louver.side);for(let x=-louver.w/2+.007;x<louver.w/2;x+=.023)box(louver.group,.014,louver.h,.012,x,0,-.51,louver.front);louver.pvcLouver=true;
